from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
draws = {
    "games/dodge/index.js": ('import { paintRounded, loadSprite } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#1b263b';ctx.fillRect(0,0,w,h);if(sprite?.complete)ctx.drawImage(sprite,player-23,h-58,46,46);else paintRounded(ctx,player-18,h-40,36,26,10,'#2dd4bf');blocks.forEach(b=>paintRounded(ctx,b.x-12,b.y,24,24,8,'#fb7185'));root.querySelector('#info').textContent=`\u041e\u0447\u043a\u0438: ${Math.round(score)}`;}"),
    "games/platformer/index.js": ('import { paintRounded, loadSprite } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#90be6d';ctx.fillRect(0,0,w,h);paintRounded(ctx,0,245,w,30,12,'#577590');if(sprite?.complete)ctx.drawImage(sprite,player.x-8,player.y-18,42,42);else paintRounded(ctx,player.x,player.y,28,28,10,'#fb7185');paintRounded(ctx,w-30,210,20,35,8,'#334155');root.querySelector('#info').textContent=`\u041c\u043e\u043d\u0435\u0442\u044b: ${Math.round(score)} · ← → \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435, \u043f\u0440\u043e\u0431\u0435\u043b \u2014 \u043f\u0440\u044b\u0436\u043e\u043a`;}"),
    "games/shooter/index.js": ('import { paintRounded, paintCircle, loadSprite } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#090b18';ctx.fillRect(0,0,w,h);paintRounded(ctx,ship-15,h-32,30,22,10,'#2dd4bf');shots.forEach(s=>paintRounded(ctx,s.x-3,s.y,6,12,3,'#fbbf24'));enemies.forEach(e=>{if(enemySprite?.complete)ctx.drawImage(enemySprite,e.x-16,e.y-16,32,32);else paintCircle(ctx,e.x,e.y,12,'#fb7185');});root.querySelector('#info').textContent=`\u0421\u0447\u0451\u0442: ${Math.round(score)} · ← → \u0438 \u043f\u0440\u043e\u0431\u0435\u043b`;}"),
    "games/snake/index.js": ('import { paintRounded, paintCircle } from "../../js/graphics.js";\n', "function draw() { const w = canvas.clientWidth, h = canvas.clientHeight, cw = w / 20, ch = h / 15; ctx.fillStyle = '#101827'; ctx.fillRect(0, 0, w, h); paintCircle(ctx, food.x*cw+cw/2, food.y*ch+ch/2, Math.min(cw,ch)*.32, '#fb7185'); snake.forEach((p,i) => paintRounded(ctx,p.x*cw+2,p.y*ch+2,cw-4,ch-4,Math.min(cw,ch)*.25,i ? '#2dd4bf' : '#fbbf24')); root.querySelector('#info').textContent = `\u0421\u0447\u0451\u0442: ${Math.round(score)}. \u0421\u0442\u0440\u0435\u043b\u043a\u0438 \u0438\u043b\u0438 \u0441\u0432\u0430\u0439\u043f \u2014 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435.`; }"),
    "games/breakout/index.js": ('import { paintRounded, paintCircle } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#101827';ctx.fillRect(0,0,w,h);bricks.forEach((r,y)=>r.forEach(b=>{if(b.on)paintRounded(ctx,b.x*w/8+2,25+y*20,w/8-4,17,6,'#fb7185')}));paintRounded(ctx,pad-35,h-12,70,7,4,'#fbbf24');paintCircle(ctx,ball.x,ball.y,7,'#2dd4bf');root.querySelector('#info').textContent=`\u0421\u0447\u0451\u0442: ${Math.round(score)}`;}"),
    "games/flappy/index.js": ('import { paintRounded, paintCircle } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#8ecae6';ctx.fillRect(0,0,w,h);pipes.forEach(p=>{paintRounded(ctx,p.x,0,36,p.gap,10,'#2a9d8f');paintRounded(ctx,p.x,p.gap+70,36,h-p.gap-70,10,'#2a9d8f')});paintCircle(ctx,bird.x,bird.y,14,'#fbbf24');paintCircle(ctx,bird.x+5,bird.y-4,3,'#17202a');root.querySelector('#info').textContent=`\u0421\u0447\u0451\u0442: ${Math.round(score)}${running?'':' \u2014 \u0441\u0442\u043e\u043b\u043a\u043d\u043e\u0432\u0435\u043d\u0438\u0435'}`;}"),
    "games/maze/index.js": ('import { paintRounded, paintCircle } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,cw=w/10,ch=h/7;ctx.fillStyle='#f1faee';ctx.fillRect(0,0,w,h);map.forEach((r,y)=>[...r].forEach((v,x)=>{if(v==='1')paintRounded(ctx,x*cw+2,y*ch+2,cw-4,ch-4,6,'#457b9d')}));paintCircle(ctx,(pos.x+.5)*cw,(pos.y+.5)*ch,Math.min(cw,ch)*.3,'#fb7185');root.querySelector('#info').textContent=running?'\u0421\u0442\u0440\u0435\u043b\u043a\u0438 \u0438\u043b\u0438 \u0441\u0432\u0430\u0439\u043f \u2014 \u043d\u0430\u0439\u0434\u0438\u0442\u0435 \u0432\u044b\u0445\u043e\u0434':'\u0412\u044b\u0445\u043e\u0434 \u043d\u0430\u0439\u0434\u0435\u043d!';}"),
    "games/pong/index.js": ('import { paintRounded, paintCircle } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.fillStyle='#101827';ctx.fillRect(0,0,w,h);paintRounded(ctx,10,p1-25,10,50,5,'#2dd4bf');paintRounded(ctx,w-20,p2-25,10,50,5,'#fbbf24');paintCircle(ctx,ball.x,ball.y,7,'#fb7185');root.querySelector('#info').textContent=`${Math.round(score[0])} : ${Math.round(score[1])}`;}"),
    "games/tetris/index.js": ('import { paintRounded } from "../../js/graphics.js";\n', "function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,cw=w/10,ch=h/20;ctx.fillStyle='#111827';ctx.fillRect(0,0,w,h);board.forEach((r,y)=>r.forEach((v,x)=>{if(v)paintRounded(ctx,x*cw+1,y*ch+1,cw-2,ch-2,5,v)}));piece?.s.forEach((r,y)=>r.forEach((v,x)=>{if(v)paintRounded(ctx,(piece.x+x)*cw+1,(piece.y+y)*ch+1,cw-2,ch-2,5,'#fb7185')}));root.querySelector('#info').textContent=`\u0421\u0447\u0451\u0442: ${Math.round(score)}`;}"),
}

for relative, (import_line, draw_line) in draws.items():
    path = ROOT / relative
    source = path.read_text(encoding="utf-8")
    if not source.startswith("import {"):
        source = import_line + source
    source = re.sub(r"function draw\([^\n]*?(?=\n(?:function|export))", draw_line, source, count=1)
    path.write_text(source, encoding="utf-8", newline="\n")
